<?php
/**
 * Built-in Skill template: image-to-article
 *
 * Guarded PHP wrapper around the SKILL.md prompt so the built-in
 * template cannot be downloaded directly over HTTP on any web server.
 * A direct request executes PHP and returns nothing; the plugin loads
 * the prompt via include from the filesystem. The body is the verbatim
 * SKILL.md content (base64 to preserve it exactly). Editable source of
 * truth lives in the public Skill Store repo. Regenerate with
 * bin/build-skill-php.php.
 */

if ( ! defined( 'ABSPATH' ) ) { exit; }

return base64_decode( '' );
